-- 002_seed.sql: the data the lesson's examples use (DML). Every row satisfies the constraints of 001_schema.sql.
--
-- The chart of accounts, and a small day (2026-10-19) of six captured payments with the six postings each of them
-- made, so the queries have something to show. `data/settlement_2026-10-19.csv` is the provider's file for that day:
-- it agrees on everything except the fee of ptx_s0002 (0.60 against the 0.52 recorded), so
-- `make reconcile-sample` finds one fee_discrepancy. The 500-payment day of the lesson is generated by
-- `make run` (the simulation), not stored here.

BEGIN;


                      idempotency_key, captured_at) VALUES
    ('bbbbbbbb-0000-4000-8000-000000000001', 'ptx_s0001', 'USD', 4250, 123, 'CAPTURED', 'SERVICE', 0, 'seed-capture-0001', '2026-10-19T10:00:00Z'),
    ('bbbbbbbb-0000-4000-8000-000000000002', 'ptx_s0002', 'USD', 1800, 52, 'CAPTURED', 'SERVICE', 0, 'seed-capture-0002', '2026-10-19T11:00:00Z'),
    ('bbbbbbbb-0000-4000-8000-000000000003', 'ptx_s0003', 'USD', 9999, 290, 'CAPTURED', 'SERVICE', 0, 'seed-capture-0003', '2026-10-19T12:00:00Z'),
    ('bbbbbbbb-0000-4000-8000-000000000004', 'ptx_s0004', 'USD', 1000, 29, 'CAPTURED', 'SERVICE', 0, 'seed-capture-0004', '2026-10-19T13:00:00Z'),
    ('bbbbbbbb-0000-4000-8000-000000000005', 'ptx_s0005', 'USD', 2500, 73, 'CAPTURED', 'SERVICE', 0, 'seed-capture-0005', '2026-10-19T14:00:00Z'),
    ('bbbbbbbb-0000-4000-8000-000000000006', 'ptx_s0006', 'USD', 500, 15, 'CAPTURED', 'SERVICE', 0, 'seed-capture-0006', '2026-10-19T15:00:00Z');



COMMIT;
